"@type":"City","name":"Brattleboro","containedInPlace":{"@type":"State","name":"Vermont"}},{"@type":"City","name":"Bennington","containedInPlace":{"@type":"State","name":"Vermont"}},{"@type":"City","name":"Middlebury","containedInPlace":{"@type":"State","name":"Vermont"}},{"@type":"City","name":"St. Johnsbury","containedInPlace":{"@type":"State","name":"Vermont"}},{"@type":"City","name":"Stowe","containedInPlace":{"@type":"State","name":"Vermont"}},{"@type":"City","name":"Hartford","containedInPlace":{"@type":"State","name":"Vermont"}}],"knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Ice dam claims","Snow load collapse","Flood and water damage claims"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://vermontinsuranceappraiser.com/#website","url":"https://vermontinsuranceappraiser.com/","name":"Vermont Insurance Appraiser","publisher":{"@id":"https://vermontinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://vermontinsuranceappraiser.com/vermont-claim-questions/#webpage","url":"https://vermontinsuranceappraiser.com/vermont-claim-questions/","name":"Vermont Insurance Claim Questions | Appraisal FAQ","description":"Vermont insurance claim questions answered by topic: how appraisal works, costs, timing, flood, ice dams and how Vermont rules fit in.","inLanguage":"en-US","isPartOf":{"@id":"https://vermontinsuranceappraiser.com/#website"},"about":{"@id":"https://vermontinsuranceappraiser.com/#business"},"publisher":{"@id":"https://vermontinsuranceappraiser.com/#business"},"dateModified":"2026-11-16","primaryImageOfPage":{"@type":"ImageObject","url":"https://vermontinsuranceappraiser.com/assets/img/photos/north-bennington-house.webp","width":1200,"height":900},"breadcrumb":{"@id":"https://vermontinsuranceappraiser.com/vermont-claim-questions/#breadcrumb"},"mainEntity":{"@id":"https://vermontinsuranceappraiser.com/#business"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://vermontinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Claim questions","item":"https://vermontinsuranceappraiser.com/vermont-claim-questions/"}],"@id":"https://vermontinsuranceappraiser.com/vermont-claim-questions/#breadcrumb"},{"@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What is insurance appraisal?","acceptedAnswer":{"@type":"Answer","text":"A process written into most property policies for resolving disagreements over the amount of a covered loss. Each side names an appraiser, the appraisers choose an umpire, and an award signed by two of the three sets the amount."}},{"@type":"Question","name":"Who can demand appraisal?","acceptedAnswer":{"@type":"Answer","text":"Most policies let either you or the insurer demand appraisal in writing. Some policies add conditions, so read the wording."}},{"@type":"Question","name":"Is appraisal the same as arbitration?","acceptedAnswer":{"@type":"Answer","text":"They are related but not identical. Appraisal is usually limited to the amount of loss, while arbitration can address broader issues. Vermont courts look at the policy language."}},{"@type":"Question","name":"Does appraisal decide coverage?","acceptedAnswer":{"@type":"Answer","text":"Generally no. If the carrier denies that the loss is covered at all, that is a coverage dispute, usually handled through a complaint to the Department of Financial Regulation or with an attorney."}},{"@type":"Question","name":"How much does appraisal cost?","acceptedAnswer":{"@type":"Answer","text":"Each side pays its own appraiser and usually half the umpire. Costs depend on the size and complexity of the claim. We quote fees in writing before starting."}},{"@type":"Question","name":"How long does it take?","acceptedAnswer":{"@type":"Answer","text":"Many residential appraisals finish within one to three months of the demand. Larger claims and scheduling can take longer."}},{"@type":"Question","name":"Is there a deadline to demand appraisal?","acceptedAnswer":{"@type":"Answer","text":"Some policies set a time limit, and the suit-limitation clause can also affect timing. Check your policy and talk to a professional if dates are close."}},{"@type":"Question","name":"What if the gap is small?","acceptedAnswer":{"@type":"Answer","text":"If the difference is small, appraisal fees may eat the recovery. A documented supplement request to the carrier is often a better first step."}},{"@type":"Question","name":"Who regulates insurance in Vermont?","acceptedAnswer":{"@type":"Answer","text":"The Vermont Department of Financial Regulation, through its Insurance Division. It licenses insurers, agents and public adjusters and handles consumer complaints."}},{"@type":"Question","name":"Does Vermont have a FAIR plan or wind pool?","acceptedAnswer":{"@type":"Answer","text":"Vermont does not operate a coastal wind pool. Hard-to-place risks are often written by surplus lines carriers. Check with the Department of Financial Regulation for current options."}},{"@type":"Question","name":"Is flood covered by a homeowners policy?","acceptedAnswer":{"@type":"Answer","text":"Usually not. Flood from rising water is generally excluded and covered under a separate flood policy, such as the National Flood Insurance Program."}},{"@type":"Question","name":"Are ice dams covered?","acceptedAnswer":{"@type":"Answer","text":"Many policies cover sudden interior water damage caused by ice dams. Some limit roof repairs or ice removal. Read the water, roof and freezing wording together."}},{"@type":"Question","name":"What about bad faith?","acceptedAnswer":{"@type":"Answer","text":"Vermont recognizes claims against insurers for bad-faith handling in some circumstances, and Title 8 lists unfair claim settlement practices. We do not give legal advice; consult a Vermont attorney."}},{"@type":"Question","name":"Are you a public adjuster?","acceptedAnswer":{"@type":"Answer","text":"No. We work as appraisers, estimators and umpires. A public adjuster handles the whole claim; we focus on the amount of loss."}},{"@type":"Question","name":"Are you lawyers?","acceptedAnswer":{"@type":"Answer","text":"No. We do not give legal advice. When a claim needs a lawyer, we say so."}},{"@type":"Question","name":"Do you work outside the big towns?","acceptedAnswer":{"@type":"Answer","text":"Yes. We work in all 14 Vermont counties, including the Northeast Kingdom and rural southern Vermont."}},{"@type":"Question","name":"Can you guarantee a result?","acceptedAnswer":{"@type":"Answer","text":"No honest appraiser can. We can promise a thorough, defensible valuation and a candid opinion about whether appraisal makes sense."}}],"@id":"https://vermontinsuranceappraiser.com/vermont-claim-questions/#faq"}]}</script>
